/* The seccomp target: execve is DEAD (the filter blocks it); the only
 * path to the flag is the open/read/write chain - the orw stub. The
 * banner announces the filter (the operator's recon reads it), no
 * addresses, no win: the shellcode slot [shellcode, orw, PATH] builds
 * the answer. NX stays ON - the shellcode must go through a writable
 * + executable page: compiled -z execstack. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/prctl.h>
#include <linux/filter.h>
#include <linux/seccomp.h>
#include <linux/audit.h>
#include <sys/syscall.h>
#include <stddef.h>

void install_filter(void) {
    /* allow: read(0) write(1) open(2) close(3) exit(60) exit_group(231).
     * Everything else (execve 59 included) dies with SIGSYS. */
    struct sock_filter filter[] = {
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_read, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_write, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_open, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_close, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_exit, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_exit_group, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_KILL_PROCESS)
    };
    struct sock_fprog prog = {13, filter};
    prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);
    prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog);
}

int vuln_copy(const char *src) {
    char small[8];
    strcpy(small, src); /* unbounded: the entry point */
    return (int) strlen(small);
}

int main(void) {
    char input[256];
    ssize_t n;

    setvbuf(stdout, NULL, _IONBF, 0);
    install_filter();
    puts("seccomp demo target - the filter allows open/read/write/exit");
    /* the leak: the buffer's address, handed over before the read (the
     * lab serves under setarch -R so the leak survives across
     * connections; a real ASLR target needs leak-and-strike in ONE
     * connection - the operator's exploit craft) */
    printf("input() at %p\n", (void *) input);
    fputs("name? ", stdout);
    n = read(0, input, sizeof(input) - 1);
    if (n <= 0) return 1;
    input[n - 1] = 0;
    vuln_copy(input);
    fputs("hello\n", stdout);
    return 0;
}
